/* Clubhouse Kitchen: native Concessions Menu, Section Settings > Custom CSS.
   Keep the Section class fdp-k-food. This field owns the complete preset;
   no source Page CSS, generated record IDs, or source Theme CSS is required. */
&.fdp-k-food {
  box-sizing: border-box;
  min-width: 0;
  padding: clamp(28px,5vw,76px) clamp(18px,5vw,72px);
  background: var(--q-background) !important;
  color: var(--q-dark) !important;
  font-family: Georgia, serif;
  font-size: 14px;
  font-weight: 400;
  line-height: 1.5;
}

/* Include the source Theme's heading treatment locally. System fonts need no import. */
&.fdp-k-food :is(h1,h2,h3,h4,.title,.poster-title) {
  color: var(--q-dark) !important;
  font-family: Georgia, "Times New Roman", serif !important;
  font-weight: 600 !important;
  letter-spacing: -.025em;
  line-height: 1.03;
  text-transform: none;
}
&.fdp-k-food h2 {
  font-size: clamp(32px,4.4vw,62px);
  line-height: 1.03;
}
&.fdp-k-food h3 {
  font-size: clamp(21px,2.1vw,30px);
  line-height: 1.15;
  margin: 0 0 14px;
}
&.fdp-k-food p {
  color: var(--q-dark);
  line-height: 1.7;
}
&.fdp-k-food :is(.text-h1,.text-h2,.text-h3,.text-h4,.text-current-color,.text-body1,.text-body2) {
  color: var(--q-dark) !important;
}

/* Native Concessions Menu owns its product layout, data, and category controls. */
&.fdp-k-food .q-card {
  background: var(--q-background);
  color: var(--q-dark);
  border: 1px solid color-mix(in srgb,var(--q-dark) 45%,var(--q-background));
  box-shadow: none;
}
&.fdp-k-food .q-tab {
  color: var(--q-dark);
}
&.fdp-k-food .q-tab--active {
  color: color-mix(in srgb,var(--q-dark) 85%,var(--q-background));
}
&.fdp-k-food :is(.q-btn,button) {
  min-height: 44px;
  border-radius: .35rem !important;
  box-shadow: none;
  font-family: Arial, "Helvetica Neue", sans-serif;
  font-weight: 700;
  letter-spacing: 0;
  text-transform: none;
}
&.fdp-k-food .q-btn.bg-primary {
  background: color-mix(in srgb,var(--q-primary) 16%,var(--q-background)) !important;
  color: var(--q-dark) !important;
  border-color: var(--q-primary) !important;
}
&.fdp-k-food .q-btn.bg-primary :is(.q-btn__content,span) {
  color: var(--q-dark) !important;
}
/* Category labels otherwise use the native black default on the source. */
&.fdp-k-food [data-category-id] .q-btn,
&.fdp-k-food [data-category-id] .q-btn :is(.q-btn__content,span) {
  color: var(--q-dark) !important;
}
&.fdp-k-food .q-focus-helper {
  border-radius: inherit;
}
&.fdp-k-food :is(a,button,.q-btn):focus-visible {
  outline: 2px solid var(--q-dark) !important;
  outline-offset: 2px;
  box-shadow: 0 0 0 4px var(--q-background) !important;
}
&.fdp-k-food .q-btn.bg-primary:hover {
  text-decoration: underline;
}

/* Preserve the native responsive grid; only contain editorial overflow. */
&.fdp-k-food * {
  box-sizing: border-box;
}
&.fdp-k-food :is(.fdp-content,.fdp-content>*,.fdp-content article,.fdp-content aside) {
  min-width: 0;
}
&.fdp-k-food :is(p,li,a) {
  overflow-wrap: break-word;
}
